// The product has one theme: dark. Apply it before the stylesheet is parsed so
// there is no light first paint, no system-preference race, and no stale
// per-tab preference that can resurrect the retired light palette.
(function(){
  document.documentElement.setAttribute('data-theme', 'dark');
  document.documentElement.classList.add('fe64-js');
  document.documentElement.classList.add('c93');
  try { var m = /(?:^|;\s*)dispatch_theme=(light|dark|system)(?:;|$)/.exec(document.cookie || ''), s = m ? m[1] : localStorage.getItem('dispatch_theme'); if (!/^(light|dark|system)$/.test(s || '')) s = 'system'; var de = document.documentElement; de.classList.remove('c97-light', 'c97-dark', 'c97-system'); de.classList.add('c97-' + s); } catch (e) { document.documentElement.classList.add('c97-system'); } // chat97 theme, before paint
})();

// chat110navy: navy shell. Theme follows the saved choice, default "system" (device); set before the stylesheet is parsed.
(function(){
  document.documentElement.classList.add('fe64-js');
  document.documentElement.classList.add('dispatch-shell');
  try {
    var m = /(?:^|;\s*)dispatch_theme=(light|dark|system)(?:;|$)/.exec(document.cookie || '');
    var s = m ? m[1] : localStorage.getItem('dispatch_theme');
    if (!/^(light|dark|system)$/.test(s || '')) s = 'system';
    var de = document.documentElement;
    var resolved = s === 'system' ? (window.matchMedia && matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light') : s;
    de.setAttribute('data-theme', resolved);
    de.classList.remove('c97-light', 'c97-dark', 'c97-system');
    de.classList.add('c97-' + s);
  } catch (e) {
    document.documentElement.setAttribute('data-theme', 'dark');
    document.documentElement.classList.add('c97-system');
  }
})();
